package mysql

import("context";"database/sql";"encoding/json";"errors";"go-repair-center/internal/repository")
type QuotationRepository struct{*CRUD;db *sql.DB;manager *DB}
func NewQuotationRepository(db *sql.DB)*QuotationRepository{return &QuotationRepository{CRUD:NewCRUD(db,"quotations",[]string{"status","customer_status"},[]string{"repair_order_id","version","labor_fee","parts_fee","inspection_fee","other_fee","total_amount","valid_until","customer_status","approval_status","approved_by","approved_at","status"}),db:db,manager:NewDB(db)}}
func(r *QuotationRepository)CreateVersion(ctx context.Context,tx *sql.Tx,input repository.Record,items []repository.Record)(repository.Record,error){repairID,ok:=input["repair_order_id"];if !ok{return nil,errors.New("repair_order_id required")};var version int;if err:=tx.QueryRowContext(ctx,"SELECT COALESCE(MAX(version),0)+1 FROM quotations WHERE repair_order_id=? FOR UPDATE",repairID).Scan(&version);err!=nil{return nil,err};result,err:=tx.ExecContext(ctx,`INSERT INTO quotations(repair_order_id,version,labor_fee,parts_fee,inspection_fee,other_fee,total_amount,valid_until,customer_status,approval_status,status) VALUES(?,?,?,?,?,?,?,?,?,?,?)`,repairID,version,input["labor_fee"],input["parts_fee"],input["inspection_fee"],input["other_fee"],input["total_amount"],input["valid_until"],input["customer_status"],input["approval_status"],input["status"]);if err!=nil{return nil,err};quotationID,_:=result.LastInsertId();for _,item:=range items{if _,err=tx.ExecContext(ctx,`INSERT INTO quotation_items(quotation_id,item_type,part_id,name,quantity,unit_price,amount,description) VALUES(?,?,?,?,?,?,?,?)`,quotationID,item["item_type"],item["part_id"],item["name"],item["quantity"],item["unit_price"],item["amount"],item["description"]);err!=nil{return nil,err}};snapshot,_:=json.Marshal(map[string]any{"quotation":input,"items":items});if _,err=tx.ExecContext(ctx,"INSERT INTO quotation_version_histories(quotation_id,version,snapshot,created_by) VALUES(?,?,?,?)",quotationID,version,string(snapshot),input["created_by"]);err!=nil{return nil,err};return repository.Record{"id":quotationID,"version":version,"repair_order_id":repairID},nil}
func(r *QuotationRepository)VersionHistory(ctx context.Context,repairOrderID int64)([]repository.Record,error){rows,err:=r.db.QueryContext(ctx,`SELECT q.*,v.snapshot FROM quotations q LEFT JOIN quotation_version_histories v ON v.quotation_id=q.id AND v.version=q.version WHERE q.repair_order_id=? AND q.deleted_at IS NULL ORDER BY q.version DESC`,repairOrderID);if err!=nil{return nil,err};defer rows.Close();items:=[]repository.Record{};for rows.Next(){item,e:=scanRecord(rows);if e!=nil{return nil,e};items=append(items,item)};return items,rows.Err()}
func(r *QuotationRepository)WithTransaction(ctx context.Context,fn func(*sql.Tx)error)error{return r.manager.WithinTransaction(ctx,fn)}